import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { randomUUID } from 'node:crypto';

import { resolveLocalProjectRoot } from './local-paths';

const PDF_STORAGE_RELATIVE_PATH = path.join('data', 'pdfs');

// Storage keys are always server-generated by savePdfFile() in this exact shape —
// see the `${Date.now()}-${randomUUID()}${extension}` template below.
const PDF_STORAGE_KEY_PATTERN = /^\d+-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.pdf$/i;

export function isValidPdfStorageKey(key: string): boolean {
  return PDF_STORAGE_KEY_PATTERN.test(key);
}

// Reasonable upper bound for scanned government-form PDF uploads.
export const MAX_PDF_UPLOAD_BYTES = 20 * 1024 * 1024; // 20 MB

/** Checks a buffer starts with the PDF magic bytes (`%PDF-`). */
export function hasPdfMagicBytes(buffer: Buffer): boolean {
  return buffer.subarray(0, 5).toString('ascii') === '%PDF-';
}

function sanitizeExtension(originalName?: string): string {
  const extension = originalName ? path.extname(originalName).toLowerCase() : '';
  return extension === '.pdf' ? extension : '.pdf';
}

function toBuffer(contents: Buffer | Uint8Array | ArrayBuffer): Buffer {
  if (Buffer.isBuffer(contents)) {
    return contents;
  }

  if (contents instanceof Uint8Array) {
    return Buffer.from(contents);
  }

  return Buffer.from(contents);
}

export function getPdfStorageDir(rootPath?: string): string {
  return path.join(resolveLocalProjectRoot(rootPath), PDF_STORAGE_RELATIVE_PATH);
}

function getPdfFilePath(filename: string, rootPath?: string): string {
  return path.join(getPdfStorageDir(rootPath), filename);
}

/**
 * Defense in depth: even though callers already reject keys that don't match
 * PDF_STORAGE_KEY_PATTERN, double-check the resolved path never escapes the
 * storage directory before touching the filesystem.
 */
function isWithinStorageDir(filePath: string, rootPath?: string): boolean {
  const storageDir = path.resolve(getPdfStorageDir(rootPath));
  const resolved = path.resolve(filePath);
  return resolved === storageDir || resolved.startsWith(storageDir + path.sep);
}

export async function savePdfFile(
  contents: Buffer | Uint8Array | ArrayBuffer,
  originalName?: string,
  rootPath?: string
): Promise<string> {
  const storageDir = getPdfStorageDir(rootPath);
  const filename = `${Date.now()}-${randomUUID()}${sanitizeExtension(originalName)}`;

  await mkdir(storageDir, { recursive: true });
  await writeFile(getPdfFilePath(filename, rootPath), toBuffer(contents));

  return filename;
}

export async function readPdfFile(filename: string, rootPath?: string): Promise<Buffer | null> {
  if (!isValidPdfStorageKey(filename)) {
    return null;
  }

  const filePath = getPdfFilePath(filename, rootPath);
  if (!isWithinStorageDir(filePath, rootPath)) {
    return null;
  }

  try {
    return await readFile(filePath);
  } catch (error) {
    const maybeNodeError = error as NodeJS.ErrnoException;
    if (maybeNodeError.code === 'ENOENT') {
      return null;
    }

    throw error;
  }
}

export async function deletePdfFile(filename: string, rootPath?: string): Promise<boolean> {
  if (!isValidPdfStorageKey(filename)) {
    return false;
  }

  const filePath = getPdfFilePath(filename, rootPath);
  if (!isWithinStorageDir(filePath, rootPath)) {
    return false;
  }

  try {
    await rm(filePath);
    return true;
  } catch (error) {
    const maybeNodeError = error as NodeJS.ErrnoException;
    if (maybeNodeError.code === 'ENOENT') {
      return false;
    }

    throw error;
  }
}
